cat > /app/output/poster.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>300 Years of Sclerosponge Thermometry - Poster</title>
  <style>
    :root{
      --bg0:#071a2b;
      --bg1:#0b2a45;
      --panel: rgba(255,255,255,0.06);
      --panel2: rgba(255,255,255,0.08);
      --stroke: rgba(255,255,255,0.14);
