      --warm:#ff4d4d;
      --warm2:#ff7b3a;
      --ok:#38d39f;
      --danger:#ff4d4d;
      --shadow: 0 30px 80px rgba(0,0,0,0.35);
      --radius: 22px;
    }

    html,body{
      height:100%;
      margin:0;
      font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
      color: var(--text);
      background: radial-gradient(1200px 1200px at 70% 25%, rgba(255,122,58,0.12), transparent 55%),
                  radial-gradient(1100px 1100px at 25% 15%, rgba(58,166,255,0.16), transparent 55%),
                  linear-gradient(160deg, var(--bg0), var(--bg1) 65%, #0c243b);
    }

    /* A0 portrait aspect (approx) */
    .poster{
      width: 2384px;
      height: 3370px;
      margin: 0 auto;
      padding: 90px 90px 80px;
