    /* subtle background texture */
    .poster::before{
      content:"";
      position:absolute;
      inset:-200px;
      background:
        radial-gradient(900px 900px at 15% 70%, rgba(58,166,255,0.10), transparent 55%),
        radial-gradient(900px 900px at 85% 80%, rgba(255,77,77,0.10), transparent 55%),
        repeating-linear-gradient(0deg, rgba(255,255,255,0.04), rgba(255,255,255,0.04) 1px, transparent 1px, transparent 14px);
      opacity:0.55;
      pointer-events:none;
      filter: blur(0.2px);
