    .poster::after{
      content:"";
      position:absolute;
      right:-180px;
      bottom:-260px;
      width: 980px;
      height: 980px;
      background:
        radial-gradient(circle at 30% 30%, rgba(58,166,255,0.10), transparent 60%),
        radial-gradient(circle at 70% 65%, rgba(255,122,58,0.10), transparent 62%),
        radial-gradient(circle at 50% 45%, rgba(255,255,255,0.05), transparent 62%);
