    .methods{
      margin-top: 18px;
      padding: 18px;
      border-top: 1px solid rgba(255,255,255,0.10);
    }

    .methods h3{
      margin:0 0 10px;
      font-size: 18px;
      text-transform: uppercase;
      letter-spacing: 0.12em;
