      gap: 20px;
      align-items:flex-end;
      color: rgba(255,255,255,0.56);
      font-size: 13px;
      letter-spacing: 0.01em;
    }

    .footnote .src{ max-width: 1600px; line-height: 1.35; }

    .qr{
      width: 150px;
      height: 150px;
      border-radius: 18px;
      border: 1px solid rgba(255,255,255,0.12);
      background: rgba(255,255,255,0.05);
      display:flex;
      align-items:center;
      justify-content:center;
      color: rgba(255,255,255,0.55);
      font-size: 12px;
      text-transform: uppercase;
      letter-spacing: 0.14em;
    }
  </style>
</head>
<body>
  <div class="poster" id="poster">
    <div class="header">
      <div class="venue">
        <span class="pill">AGU / Nature Climate Change Symposium</span>
        <span class="pill">Sclerosponge Sr/Ca proxy • Caribbean reef sites • Annual resolution</span>
      </div>
      <h1 class="title">300 Years of Sclerosponge Thermometry Shows Global Warming Has Exceeded 1.5&nbsp;°C</h1>
      <p class="subtitle">A marine proxy reconstruction extending back to ~1700 CE shows that the commonly used 1850–1900 “pre‑industrial” reference already included ~0.5&nbsp;°C of anthropogenic warming. Using a true pre‑industrial baseline (1700–1790) implies total warming is ~0.5&nbsp;°C higher than conventional estimates — and the 1.5&nbsp;°C Paris threshold has already been crossed.</p>
    </div>

    <div class="content">
      <!-- LEFT: TIMELINE CENTERPIECE -->
      <div class="panel timeline">
        <div class="panel-header">
          <h2>300-Year Temperature Reconstruction</h2>
          <p class="note">Temperature anomaly relative to the 1700–1790 mean (true pre‑industrial baseline).</p>
        </div>

        <div class="timeline-body">
          <div class="callouts">
            <div class="callout">
              <div class="kicker">Key finding</div>
              <p class="big big-accent">“Hidden” +0.5&nbsp;°C</p>
              <div class="small">The 1850–1900 reference period is already ~0.5&nbsp;°C warmer than 1700–1790. Instrumental‑era warming is therefore systematically understated.</div>
            </div>
            <div class="callout">
              <div class="kicker">Threshold status</div>
              <p class="big big-warm">&gt;1.5&nbsp;°C exceeded</p>
              <div class="small">The reconstruction crosses 1.5&nbsp;°C in the early 2010s and reaches ~1.7&nbsp;°C by ~2020 (vs. ~1.2&nbsp;°C reported using 1850–1900).</div>
            </div>
          </div>

          <div class="chart-wrap">
            <div id="chart"></div>
            <div class="overlay">
              <div class="badge"><span class="dot warm"></span><span><strong>1.5&nbsp;°C</strong> Paris threshold (relative to 1700–1790)</span></div>
              <div class="badge"><span class="dot"></span><span><strong>Crossing:</strong> ~2013 (highlighted)</span></div>
              <div class="badge"><span class="dot cool"></span><span><strong>1850–1900</strong> mean is ~+0.5&nbsp;°C above true pre‑industrial</span></div>
            </div>
          </div>
        </div>

        <div class="timeline-footer">
          <div class="footer-box">
            <h3>Milestones</h3>
            <p>1700–1790 stable baseline • 1790–1850 onset of detectable warming • 1850–1900 already +0.5&nbsp;°C • post‑1960 acceleration • early‑2010s crossing of 1.5&nbsp;°C • early‑2020s ~1.7&nbsp;°C.</p>
          </div>
          <div class="footer-box">
            <h3>Interpretation</h3>
            <p>Aligning “pre‑industrial” with a true baseline reduces the remaining 1.5&nbsp;°C carbon budget to effectively zero and brings the 2.0&nbsp;°C guardrail closer than implied by standard 1850–1900 framing.</p>
          </div>
        </div>
      </div>

      <!-- RIGHT COLUMN: STATS + COMPARISON + METHODS -->
      <div class="side">
        <div class="panel">
          <div class="panel-header">
            <h2>At-a-Glance Metrics</h2>
            <p class="note">Scannable numbers for rapid comprehension.</p>
          </div>
          <div class="stats">
            <div class="stat">
              <div class="label">Record length</div>
              <div class="value">~300 years<br/><span style="color:rgba(255,255,255,0.68); font-weight:650; font-size:16px;">(~1700 CE to present)</span></div>
            </div>
            <div class="stat">
              <div class="label">Proxy source</div>
              <div class="value"><strong>Sr/Ca</strong> in sclerosponge<br/><span style="color:rgba(255,255,255,0.68); font-weight:650; font-size:16px;">Caribbean reef skeletons</span></div>
            </div>
            <div class="stat">
              <div class="label">Hidden warming</div>
              <div class="value"><strong>~0.5&nbsp;°C</strong><br/><span style="color:rgba(255,255,255,0.68); font-weight:650; font-size:16px;">already by 1850–1900</span></div>
            </div>
            <div class="stat">
              <div class="label">Threshold status</div>
              <div class="value"><strong>&gt;1.5&nbsp;°C</strong><br/><span style="color:rgba(255,255,255,0.68); font-weight:650; font-size:16px;">exceeded by early 2020s</span></div>
            </div>
          </div>
        </div>

        <div class="panel">
          <div class="panel-header">
            <h2>Pre-Industrial Baseline Matters</h2>
            <p class="note">A direct comparison of warming estimates.</p>
          </div>
          <div class="compare">
            <div class="compare-row">
              <div class="compare-card">
                <div class="hdr"><div class="t">IPCC framing</div><div class="badge"><span class="dot cool"></span><span>1850–1900 baseline</span></div></div>
                <div class="temp" style="color: rgba(58,166,255,0.98);">~1.2&nbsp;°C</div>
                <p class="desc">Warming to ~2020 using instrumental reference periods (e.g., HadCRUT5 / IPCC AR6 conventions).</p>
              </div>
              <div class="compare-card">
                <div class="hdr"><div class="t">True baseline</div><div class="badge"><span class="dot warm"></span><span>1700–1790 baseline</span></div></div>
                <div class="temp" style="color: rgba(255,77,77,0.98);">~1.7&nbsp;°C</div>
                <p class="desc">Warming to ~2020 when referenced to a true pre‑industrial mean inferred from sclerosponge proxies.</p>
              </div>
            </div>
            <div class="divider"></div>
            <div class="compare-card" style="background: linear-gradient(90deg, rgba(58,166,255,0.08), rgba(255,77,77,0.08));">
              <div class="hdr"><div class="t">Difference</div><div class="badge"><span class="dot"></span><span>Baseline bias</span></div></div>
              <div class="temp" style="color: rgba(255,176,32,0.98);">~0.5&nbsp;°C</div>
              <p class="desc">Approximately half a degree of anthropogenic warming occurs before 1850, so starting “pre‑industrial” at 1850–1900 masks part of the total signal.</p>
            </div>
          </div>
        </div>

        <div class="panel" style="display:flex; flex-direction:column;">
          <div class="panel-header">
            <h2>Policy & Methods</h2>
            <p class="note">What changes and why the proxy is robust.</p>
          </div>
          <div class="list">
            <h3>Implications</h3>
            <ul class="bullets">
              <li>“1.5&nbsp;°C” is defined relative to pre‑industrial; the operational 1850–1900 reference is not fully pre‑industrial.</li>
              <li>Adopting a 1700–1790 baseline effectively eliminates the remaining 1.5&nbsp;°C carbon budget.</li>
              <li>The 2.0&nbsp;°C guardrail is closer: ~0.3&nbsp;°C remaining rather than ~0.8&nbsp;°C.</li>
            </ul>
          </div>
          <div class="methods">
            <h3>Data & Methods Summary</h3>
            <p>Sclerosponge Sr/Ca ratios (aragonite skeletons) provide continuous annual‑resolution SST proxies across ~300 years. Specimens were collected from Caribbean reef environments (33–91&nbsp;m depth). Sr/Ca was measured via ICP‑OES and calibrated against co‑located instrumental SST from ~1960 onward (r² &gt; 0.9). The reconstruction agrees with HadCRUT5 and NOAA ERSSTv5 during the instrumental era and diverges primarily before ~1850 — precisely where the hidden warming resides.</p>
          </div>
        </div>
      </div>
    </div>

    <div class="footnote">
      <div class="src">Source synthesis: Nature Climate Change (2024) sclerosponge thermometry study; instrumental comparators (HadCRUT5 / NOAA ERSSTv5) referenced in the study summary. The plotted curve is a stylized reconstruction anchored to reported key constraints (1700–1790 baseline; 1850–1900 mean ~+0.5&nbsp;°C; ~2020 ~+1.7&nbsp;°C; crossing ~early‑2010s) for communication purposes.</div>
      <div class="qr">Figure</div>
    </div>
  </div>

  <script src="/app/vendor/infographic.min.js"></script>
  <!-- Using AntV G2 for the centerpiece chart (bundled via infographic dependency in most builds). If not present, we fall back to inline SVG. -->
  <script>
    // Downsampled values: year, anomaly (°C) relative to 1700–1790.
    const series = [
      [1700,-0.00],[1710,0.03],[1720,-0.07],[1730,-0.04],[1740,0.03],[1750,-0.01],[1760,0.04],[1770,-0.04],[1780,-0.02],[1790,-0.01],
      [1800,0.08],[1810,0.15],[1820,0.21],[1830,0.33],[1840,0.37],[1850,0.45],[1860,0.53],[1870,0.50],[1880,0.47],[1890,0.52],
      [1900,0.59],[1910,0.62],[1920,0.66],[1930,0.68],[1940,0.70],[1950,0.74],[1960,0.76],[1970,0.88],[1980,0.98],[1990,1.08],
      [2000,1.23],[2001,1.25],[2002,1.27],[2003,1.30],[2004,1.33],[2005,1.35],[2006,1.38],[2007,1.40],[2008,1.42],[2009,1.44],
      [2010,1.47],[2011,1.49],[2012,1.50],[2013,1.52],[2014,1.55],[2015,1.58],[2016,1.62],[2017,1.64],[2018,1.66],[2019,1.68],
      [2020,1.70],[2021,1.73],[2022,1.76],[2023,1.78],[2024,1.80]
    ].map(([year, anomaly]) => ({ year, anomaly }));

    const crossingYear = 2013;

    function tryRenderG2() {
      const G2 = (window.G2 || (window.AntV && window.AntV.G2));
      if (!G2) return false;

      const chart = new G2.Chart({
        container: 'chart',
        autoFit: true,
        height: document.getElementById('chart').clientHeight,
        padding: [40, 55, 55, 65],
        theme: {
          background: 'transparent',
        },
      });

      chart.data(series);

      chart.scale({
        year: { type: 'linear', tickCount: 8 },
        anomaly: { min: -0.2, max: 1.9, tickCount: 8 },
      });

      chart.axis('year', {
        label: { style: { fill: 'rgba(255,255,255,0.70)', fontSize: 12 } },
        line: { style: { stroke: 'rgba(255,255,255,0.16)' } },
        tickLine: { style: { stroke: 'rgba(255,255,255,0.12)' } },
        grid: { line: { style: { stroke: 'rgba(255,255,255,0.08)', lineDash: [4,4] } } },
      });

      chart.axis('anomaly', {
        title: null,
        label: { style: { fill: 'rgba(255,255,255,0.70)', fontSize: 12 } },
        line: { style: { stroke: 'rgba(255,255,255,0.16)' } },
        tickLine: { style: { stroke: 'rgba(255,255,255,0.12)' } },
        grid: { line: { style: { stroke: 'rgba(255,255,255,0.08)', lineDash: [4,4] } } },
      });

      // Line with cool-to-warm gradient emulation via color mapping by anomaly
      chart.line()
        .position('year*anomaly')
        .shape('smooth')
        .color('anomaly', (v) => {
          // piecewise: blue -> amber -> red
          if (v < 0.6) return 'rgba(58,166,255,0.95)';
          if (v < 1.2) return 'rgba(255,176,32,0.95)';
          return 'rgba(255,77,77,0.95)';
        })
        .style({ lineWidth: 3 });

      // Area under curve (subtle)
      chart.area()
        .position('year*anomaly')
