            <h2>Pre-Industrial Baseline Matters</h2>
            <p class="note">A direct comparison of warming estimates.</p>
          </div>
          <div class="compare">
            <div class="compare-row">
              <div class="compare-card">
                <div class="hdr"><div class="t">IPCC framing</div><div class="badge"><span class="dot cool"></span><span>1850–1900 baseline</span></div></div>
                <div class="temp" style="color: rgba(58,166,255,0.98);">~1.2&nbsp;°C</div>
                <p class="desc">Warming to ~2020 using instrumental reference periods (e.g., HadCRUT5 / IPCC AR6 conventions).</p>
              </div>
              <div class="compare-card">
                <div class="hdr"><div class="t">True baseline</div><div class="badge"><span class="dot warm"></span><span>1700–1790 baseline</span></div></div>
                <div class="temp" style="color: rgba(255,77,77,0.98);">~1.7&nbsp;°C</div>
                <p class="desc">Warming to ~2020 when referenced to a true pre‑industrial mean inferred from sclerosponge proxies.</p>
              </div>
            </div>
            <div class="divider"></div>
            <div class="compare-card" style="background: linear-gradient(90deg, rgba(58,166,255,0.08), rgba(255,77,77,0.08));">
              <div class="hdr"><div class="t">Difference</div><div class="badge"><span class="dot"></span><span>Baseline bias</span></div></div>
              <div class="temp" style="color: rgba(255,176,32,0.98);">~0.5&nbsp;°C</div>
              <p class="desc">Approximately half a degree of anthropogenic warming occurs before 1850, so starting “pre‑industrial” at 1850–1900 masks part of the total signal.</p>
            </div>
          </div>
        </div>

        <div class="panel" style="display:flex; flex-direction:column;">
          <div class="panel-header">
            <h2>Policy & Methods</h2>
            <p class="note">What changes and why the proxy is robust.</p>
          </div>
          <div class="list">
            <h3>Implications</h3>
            <ul class="bullets">
              <li>“1.5&nbsp;°C” is defined relative to pre‑industrial; the operational 1850–1900 reference is not fully pre‑industrial.</li>
              <li>Adopting a 1700–1790 baseline effectively eliminates the remaining 1.5&nbsp;°C carbon budget.</li>
              <li>The 2.0&nbsp;°C guardrail is closer: ~0.3&nbsp;°C remaining rather than ~0.8&nbsp;°C.</li>
            </ul>
          </div>
          <div class="methods">
            <h3>Data & Methods Summary</h3>
            <p>Sclerosponge Sr/Ca ratios (aragonite skeletons) provide continuous annual‑resolution SST proxies across ~300 years. Specimens were collected from Caribbean reef environments (33–91&nbsp;m depth). Sr/Ca was measured via ICP‑OES and calibrated against co‑located instrumental SST from ~1960 onward (r² &gt; 0.9). The reconstruction agrees with HadCRUT5 and NOAA ERSSTv5 during the instrumental era and diverges primarily before ~1850 — precisely where the hidden warming resides.</p>
          </div>
        </div>
      </div>
    </div>

    <div class="footnote">
      <div class="src">Source synthesis: Nature Climate Change (2024) sclerosponge thermometry study; instrumental comparators (HadCRUT5 / NOAA ERSSTv5) referenced in the study summary. The plotted curve is a stylized reconstruction anchored to reported key constraints (1700–1790 baseline; 1850–1900 mean ~+0.5&nbsp;°C; ~2020 ~+1.7&nbsp;°C; crossing ~early‑2010s) for communication purposes.</div>
      <div class="qr">Figure</div>
    </div>
  </div>

  <script src="/app/vendor/infographic.min.js"></script>
  <!-- Using AntV G2 for the centerpiece chart (bundled via infographic dependency in most builds). If not present, we fall back to inline SVG. -->
  <script>
    // Downsampled values: year, anomaly (°C) relative to 1700–1790.
    const series = [
      [1700,-0.00],[1710,0.03],[1720,-0.07],[1730,-0.04],[1740,0.03],[1750,-0.01],[1760,0.04],[1770,-0.04],[1780,-0.02],[1790,-0.01],
      [1800,0.08],[1810,0.15],[1820,0.21],[1830,0.33],[1840,0.37],[1850,0.45],[1860,0.53],[1870,0.50],[1880,0.47],[1890,0.52],
      [1900,0.59],[1910,0.62],[1920,0.66],[1930,0.68],[1940,0.70],[1950,0.74],[1960,0.76],[1970,0.88],[1980,0.98],[1990,1.08],
      [2000,1.23],[2001,1.25],[2002,1.27],[2003,1.30],[2004,1.33],[2005,1.35],[2006,1.38],[2007,1.40],[2008,1.42],[2009,1.44],
      [2010,1.47],[2011,1.49],[2012,1.50],[2013,1.52],[2014,1.55],[2015,1.58],[2016,1.62],[2017,1.64],[2018,1.66],[2019,1.68],
      [2020,1.70],[2021,1.73],[2022,1.76],[2023,1.78],[2024,1.80]
    ].map(([year, anomaly]) => ({ year, anomaly }));

    const crossingYear = 2013;

    function tryRenderG2() {
      const G2 = (window.G2 || (window.AntV && window.AntV.G2));
      if (!G2) return false;

      const chart = new G2.Chart({
        container: 'chart',
        autoFit: true,
        height: document.getElementById('chart').clientHeight,
        padding: [40, 55, 55, 65],
        theme: {
          background: 'transparent',
        },
      });

      chart.data(series);

      chart.scale({
        year: { type: 'linear', tickCount: 8 },
        anomaly: { min: -0.2, max: 1.9, tickCount: 8 },
      });

      chart.axis('year', {
        label: { style: { fill: 'rgba(255,255,255,0.70)', fontSize: 12 } },
        line: { style: { stroke: 'rgba(255,255,255,0.16)' } },
        tickLine: { style: { stroke: 'rgba(255,255,255,0.12)' } },
        grid: { line: { style: { stroke: 'rgba(255,255,255,0.08)', lineDash: [4,4] } } },
      });

      chart.axis('anomaly', {
        title: null,
        label: { style: { fill: 'rgba(255,255,255,0.70)', fontSize: 12 } },
        line: { style: { stroke: 'rgba(255,255,255,0.16)' } },
        tickLine: { style: { stroke: 'rgba(255,255,255,0.12)' } },
        grid: { line: { style: { stroke: 'rgba(255,255,255,0.08)', lineDash: [4,4] } } },
      });

      // Line with cool-to-warm gradient emulation via color mapping by anomaly
      chart.line()
        .position('year*anomaly')
        .shape('smooth')
        .color('anomaly', (v) => {
          // piecewise: blue -> amber -> red
          if (v < 0.6) return 'rgba(58,166,255,0.95)';
          if (v < 1.2) return 'rgba(255,176,32,0.95)';
          return 'rgba(255,77,77,0.95)';
        })
        .style({ lineWidth: 3 });

      // Area under curve (subtle)
      chart.area()
        .position('year*anomaly')
        .shape('smooth')
        .color('anomaly', (v) => {
          if (v < 0.6) return 'rgba(58,166,255,0.10)';
          if (v < 1.2) return 'rgba(255,176,32,0.10)';
          return 'rgba(255,77,77,0.10)';
        })
        .style({ fillOpacity: 1 });

      // 1.5°C threshold line
      chart.annotation().line({
        start: ['min', 1.5],
        end: ['max', 1.5],
        style: {
          stroke: 'rgba(255,77,77,0.85)',
          lineDash: [8,6],
          lineWidth: 2,
        },
        text: {
          content: '1.5°C',
          position: 'end',
          offsetY: -8,
          style: { fill: 'rgba(255,77,77,0.90)', fontSize: 12, fontWeight: 700 },
        }
      });

      // Highlight crossing point
      const crossPoint = series.find(d => d.year === crossingYear);
      if (crossPoint) {
        chart.annotation().dataMarker({
          position: [crossPoint.year, crossPoint.anomaly],
          point: {
            style: {
              r: 6,
              fill: 'rgba(255,176,32,0.98)',
              stroke: 'rgba(255,255,255,0.85)',
              lineWidth: 2,
            },
          },
          text: {
            content: 'Crossing (~2013)',
            style: {
              fill: 'rgba(255,255,255,0.85)',
              fontSize: 12,
              fontWeight: 650,
            },
            offsetX: 10,
            offsetY: -18,
          },
          line: {
            length: 30,
            style: { stroke: 'rgba(255,255,255,0.35)', lineDash: [4,4] },
          },
        });
      }

      // Baseline band note: 1850-1900 mean ~0.5
      chart.annotation().region({
        start: [1850, -0.2],
        end: [1900, 0.5],
        style: {
          fill: 'rgba(58,166,255,0.10)',
          stroke: 'rgba(58,166,255,0.18)',
          lineWidth: 1,
        },
      });

      chart.render();
      return true;
    }

    function renderFallbackSVG() {
      const el = document.getElementById('chart');
      const w = el.clientWidth;
      const h = el.clientHeight;
      const pad = {t: 46, r: 40, b: 54, l: 70};
      const innerW = w - pad.l - pad.r;
      const innerH = h - pad.t - pad.b;

      const minX = 1700, maxX = 2024;
      const minY = -0.2, maxY = 1.9;

      const x = (year) => pad.l + (year - minX) / (maxX - minX) * innerW;
      const y = (val) => pad.t + (maxY - val) / (maxY - minY) * innerH;

      // grid
      const xTicks = [1700,1750,1800,1850,1900,1950,2000,2024];
      const yTicks = [-0.0,0.5,1.0,1.5];

      // path
      let d = '';
      series.forEach((p,i)=>{
        const px = x(p.year), py = y(p.anomaly);
        d += (i===0?`M ${px.toFixed(2)} ${py.toFixed(2)}`:` L ${px.toFixed(2)} ${py.toFixed(2)}`);
      });

      const cross = series.find(p => p.year === crossingYear);

      const svg = `
      <svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="rgba(58,166,255,0.95)"/>
            <stop offset="55%" stop-color="rgba(255,176,32,0.95)"/>
            <stop offset="100%" stop-color="rgba(255,77,77,0.95)"/>
          </linearGradient>
        </defs>

        <rect x="0" y="0" width="${w}" height="${h}" fill="transparent"/>

        ${xTicks.map(tx=>`<line x1="${x(tx)}" y1="${pad.t}" x2="${x(tx)}" y2="${h-pad.b}" stroke="rgba(255,255,255,0.08)" stroke-dasharray="4 4"/>`).join('')}
        ${yTicks.map(ty=>`<line x1="${pad.l}" y1="${y(ty)}" x2="${w-pad.r}" y2="${y(ty)}" stroke="rgba(255,255,255,0.08)" stroke-dasharray="4 4"/>`).join('')}

        <line x1="${pad.l}" y1="${y(1.5)}" x2="${w-pad.r}" y2="${y(1.5)}" stroke="rgba(255,77,77,0.85)" stroke-width="2" stroke-dasharray="8 6"/>
        <text x="${w-pad.r}" y="${y(1.5)-10}" text-anchor="end" fill="rgba(255,77,77,0.90)" font-size="12" font-weight="700">1.5°C</text>

        <path d="${d}" fill="none" stroke="url(#lineGrad)" stroke-width="3"/>

        ${cross ? `
          <circle cx="${x(cross.year)}" cy="${y(cross.anomaly)}" r="7" fill="rgba(255,176,32,0.98)" stroke="rgba(255,255,255,0.85)" stroke-width="2"/>
          <line x1="${x(cross.year)}" y1="${y(cross.anomaly)}" x2="${x(cross.year)+36}" y2="${y(cross.anomaly)-24}" stroke="rgba(255,255,255,0.35)" stroke-dasharray="4 4"/>
          <text x="${x(cross.year)+40}" y="${y(cross.anomaly)-28}" fill="rgba(255,255,255,0.85)" font-size="12" font-weight="650">Crossing (~2013)</text>
        ` : ''}

        <rect x="${x(1850)}" y="${y(0.5)}" width="${x(1900)-x(1850)}" height="${y(-0.2)-y(0.5)}" fill="rgba(58,166,255,0.10)" stroke="rgba(58,166,255,0.18)"/>

        <line x1="${pad.l}" y1="${h-pad.b}" x2="${w-pad.r}" y2="${h-pad.b}" stroke="rgba(255,255,255,0.16)"/>
        <line x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${h-pad.b}" stroke="rgba(255,255,255,0.16)"/>

        ${xTicks.map(tx=>`<text x="${x(tx)}" y="${h-pad.b+22}" text-anchor="middle" fill="rgba(255,255,255,0.70)" font-size="12">${tx}</text>`).join('')}
        ${yTicks.map(ty=>`<text x="${pad.l-10}" y="${y(ty)+4}" text-anchor="end" fill="rgba(255,255,255,0.70)" font-size="12">${ty.toFixed(1)}</text>`).join('')}

        <text x="${pad.l}" y="${pad.t-18}" fill="rgba(255,255,255,0.78)" font-size="12" font-weight="650">Anomaly (°C)</text>
      </svg>`;

      el.innerHTML = svg;
    }

    const ok = tryRenderG2();
    if (!ok) renderFallbackSVG();
  </script>
</body>
